// ADC/DAC setup not yet generated by CubeMX; see README.md, IOC gaps.

#include "adc.h"
#include "board.hpp"
#include "dac.h"

namespace vcu_board {

TIM_HandleTypeDef htim6;
TIM_HandleTypeDef htim7;
DMA_HandleTypeDef hdma_adc2;
DMA_HandleTypeDef hdma_dac1;
volatile uint16_t g_adc1_buffer[vcu::kAdc1Channels] = {};
volatile uint16_t g_adc2_buffer[vcu::kAdc2Channels] = {};
std::atomic<uint32_t> g_adc1_scans{0};
std::atomic<uint32_t> g_adc2_scans{0};

namespace {

constexpr uint32_t kAdcTriggerHz = 1000;
constexpr uint32_t kTimerTickHz = 1000000;

// APB1 timers run at PCLK1, doubled when the APB1 prescaler isn't 1.
uint32_t Apb1TimerClockHz() {
  const uint32_t pclk = HAL_RCC_GetPCLK1Freq();
  return (RCC->CFGR & RCC_CFGR_PPRE1_2) != 0 ? pclk * 2 : pclk;
}

void Check(HAL_StatusTypeDef s) {
  if (s != HAL_OK) {
    Error_Handler();
  }
}

void ConfigureBasicTimer(TIM_HandleTypeDef* htim, TIM_TypeDef* instance,
                         uint32_t prescaler, uint32_t period) {
  htim->Instance = instance;
  htim->Init.Prescaler = prescaler;
  htim->Init.CounterMode = TIM_COUNTERMODE_UP;
  htim->Init.Period = period;
  htim->Init.AutoReloadPreload = TIM_AUTORELOAD_PRELOAD_DISABLE;
  Check(HAL_TIM_Base_Init(htim));
  TIM_MasterConfigTypeDef master = {};
  master.MasterOutputTrigger = TIM_TRGO_UPDATE;
  master.MasterOutputTrigger2 = TIM_TRGO2_RESET;
  master.MasterSlaveMode = TIM_MASTERSLAVEMODE_DISABLE;
  Check(HAL_TIMEx_MasterConfigSynchronization(htim, &master));
}

void AddRank(ADC_HandleTypeDef* hadc, uint32_t channel, uint32_t rank,
             uint32_t sampling) {
  ADC_ChannelConfTypeDef c = {};
  c.Channel = channel;
  c.Rank = rank;
  c.SamplingTime = sampling;
  c.SingleDiff = ADC_SINGLE_ENDED;
  c.OffsetNumber = ADC_OFFSET_NONE;
  c.Offset = 0;
  Check(HAL_ADC_ConfigChannel(hadc, &c));
}

void TriggeredScan(ADC_HandleTypeDef* hadc, uint32_t conversions) {
  hadc->Init.ScanConvMode = ADC_SCAN_ENABLE;
  hadc->Init.NbrOfConversion = conversions;
  hadc->Init.ContinuousConvMode = DISABLE;
  hadc->Init.ExternalTrigConv = ADC_EXTERNALTRIG_T6_TRGO;
  hadc->Init.ExternalTrigConvEdge = ADC_EXTERNALTRIGCONVEDGE_RISING;
  hadc->Init.DMAContinuousRequests = ENABLE;
  hadc->Init.Overrun = ADC_OVR_DATA_OVERWRITTEN;
  // 16 conversions averaged in hardware per trigger, still 12-bit.
  hadc->Init.OversamplingMode = ENABLE;
  hadc->Init.Oversampling.Ratio = ADC_OVERSAMPLING_RATIO_16;
  hadc->Init.Oversampling.RightBitShift = ADC_RIGHTBITSHIFT_4;
  hadc->Init.Oversampling.TriggeredMode = ADC_TRIGGEREDMODE_SINGLE_TRIGGER;
  hadc->Init.Oversampling.OversamplingStopReset =
      ADC_REGOVERSAMPLING_CONTINUED_MODE;
  Check(HAL_ADC_Init(hadc));
}

void CircularDma(DMA_HandleTypeDef* hdma, DMA_Channel_TypeDef* channel,
                 uint32_t request, uint32_t direction) {
  hdma->Instance = channel;
  hdma->Init.Request = request;
  hdma->Init.Direction = direction;
  hdma->Init.PeriphInc = DMA_PINC_DISABLE;
  hdma->Init.MemInc = DMA_MINC_ENABLE;
  hdma->Init.PeriphDataAlignment = DMA_PDATAALIGN_HALFWORD;
  hdma->Init.MemDataAlignment = DMA_MDATAALIGN_HALFWORD;
  hdma->Init.Mode = DMA_CIRCULAR;
  hdma->Init.Priority = DMA_PRIORITY_MEDIUM;
  Check(HAL_DMA_Init(hdma));
}

}  // namespace

void ConfigureAnalog() {
  // ADC1 ranks 1-4 come from CubeMX. VREFINT needs at least 4 us sampling.
  TriggeredScan(&hadc1, vcu::kAdc1Channels);
  AddRank(&hadc1, ADC_CHANNEL_4, ADC_REGULAR_RANK_5, ADC_SAMPLETIME_92CYCLES_5);
  AddRank(&hadc1, ADC_CHANNEL_VREFINT, ADC_REGULAR_RANK_6,
          ADC_SAMPLETIME_247CYCLES_5);

  // ADC2: steering (rank 1 from CubeMX), then Shutdown_in_S.
  CircularDma(&hdma_adc2, DMA1_Channel2, DMA_REQUEST_ADC2,
              DMA_PERIPH_TO_MEMORY);
  __HAL_LINKDMA(&hadc2, DMA_Handle, hdma_adc2);
  TriggeredScan(&hadc2, vcu::kAdc2Channels);
  AddRank(&hadc2, ADC_CHANNEL_11, ADC_REGULAR_RANK_2,
          ADC_SAMPLETIME_92CYCLES_5);
  HAL_NVIC_SetPriority(DMA1_Channel2_IRQn, 10, 0);
  HAL_NVIC_EnableIRQ(DMA1_Channel2_IRQn);

  __HAL_RCC_TIM6_CLK_ENABLE();
  ConfigureBasicTimer(&htim6, TIM6, Apb1TimerClockHz() / kTimerTickHz - 1,
                      kTimerTickHz / kAdcTriggerHz - 1);

  // DAC1 CH1 (Audio_DAC, PA4): buffered, triggered by TIM7, fed by DMA.
  __HAL_RCC_TIM7_CLK_ENABLE();
  ConfigureBasicTimer(&htim7, TIM7, 0, 0xFFFF);
  CircularDma(&hdma_dac1, DMA1_Channel3, DMA_REQUEST_DAC1_CHANNEL1,
              DMA_MEMORY_TO_PERIPH);
  __HAL_LINKDMA(&hdac1, DMA_Handle1, hdma_dac1);
  DAC_ChannelConfTypeDef dac = {};
  dac.DAC_HighFrequency = DAC_HIGH_FREQUENCY_INTERFACE_MODE_AUTOMATIC;
  dac.DAC_DMADoubleDataMode = DISABLE;
  dac.DAC_SignedFormat = DISABLE;
  dac.DAC_SampleAndHold = DAC_SAMPLEANDHOLD_DISABLE;
  dac.DAC_Trigger = DAC_TRIGGER_T7_TRGO;
  dac.DAC_Trigger2 = DAC_TRIGGER_NONE;
  dac.DAC_OutputBuffer = DAC_OUTPUTBUFFER_ENABLE;
  dac.DAC_ConnectOnChipPeripheral = DAC_CHIPCONNECT_EXTERNAL;
  dac.DAC_UserTrimming = DAC_TRIMMING_FACTORY;
  Check(HAL_DAC_ConfigChannel(&hdac1, &dac, DAC_CHANNEL_1));
  HAL_NVIC_SetPriority(DMA1_Channel3_IRQn, 10, 0);
  HAL_NVIC_EnableIRQ(DMA1_Channel3_IRQn);
}

void StartAdcTrigger() { Check(HAL_TIM_Base_Start(&htim6)); }

}  // namespace vcu_board

extern "C" void HAL_ADC_ConvCpltCallback(ADC_HandleTypeDef* hadc) {
  if (hadc == &hadc1) {
    vcu_board::g_adc1_scans.fetch_add(1);
  } else if (hadc == &hadc2) {
    vcu_board::g_adc2_scans.fetch_add(1);
  }
}
